def digit_sum(x):
    s = 0
    while x > 0:
        s += x % 10
        x = x // 10
    return s

def reverse_number(k):
    out = 0
    while k:
        out = out * 10 + k % 10
        k //= 10
    return out

def parse_int(t):
    v = 0
    for c in t:
        if c < '0' or c > '9':
            break
        v = v * 10 + ord(c) - 48
    return v

def is_lower(letter):
    return letter >= 'a' and letter <= 'z'

def shift(letter):
    return chr(ord(letter) - 32)

def to_hex(d):
    if d >= 10:
        return chr(ord('A') + d - 10)
    return chr(ord('0') + d)

