def total_size(items):
    s = 0
    for item in items:
        s += item.size
    return s

def reverse_list(k):
    out = []
    while k:
        out.append(k.pop())
    return out

def parse_line(t):
    v = {}
    for part in t.split(','):
        key, val = part.split('=')
        v[key] = val
    return v

def is_admin(person):
    return person.role == 'admin' and person.active

def greet(person):
